window.products.push({"id":489785,"name":"HomeReady 950g Extra Strength Bamboo Charcoal Air Purifying Bags (6 Pack - Gray Linen) Natural Activated Charcoal Absorbs Odors from Bathrooms, Closet","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/61qU-eVUmEL._AC_SL1112_.jpg","description":"HomeReady bamboo charcoal air purifying bags are made with real, all-natural bamboo, wrapped in cotton linen. Activated charcoal has tiny pores that trap odors and absorb excess moisture in the air, so HomeReady bags work great in shoes, closets, fridges, gym bags, cars - anywhere you want to freshen the air. Best of all - they're reusable! Simply set them out in the sun for a few hours every month or two and you'll refresh them.","images":["https://m.media-amazon.com/images/I/61qU-eVUmEL._AC_SL1112_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"HomeReady","source_asin":"B07TLX71CD","category_path":"Home & Kitchen"},"sku":"BM-489785","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B07TLX71CD","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B07TLX71CD","price_pending":true,"merchant_ready":false});
